-- ====================================
-- IT Ticket System - Database Schema 
-- ====================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ---------------------------------------------------------------------
-- admin_tb: บัญชีแอดมินที่ต้อง login ด้วยเบอร์โทร/รหัสผ่าน (อีเมลเป็นข้อมูลเสริม)
-- ---------------------------------------------------------------------
CREATE TABLE "admin_tb" (
  "admin_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "admin_full_name" varchar NOT NULL,
  "admin_phone" varchar UNIQUE,
  "admin_email" varchar UNIQUE,
  "admin_password_hash" varchar NOT NULL,
  "admin_must_change_password" boolean NOT NULL DEFAULT false,
  "admin_role" varchar NOT NULL DEFAULT 'admin',
  "admin_is_active" boolean NOT NULL DEFAULT true,
  -- อ้างถึง department_tb: NULL = super admin (เห็น/จัดการตั๋วได้ทุกแผนก) ไม่ NULL = แอดมินแผนกนั้นเท่านั้น
  "admin_department_id" integer,
  "admin_create_date" timestamptz NOT NULL DEFAULT now(),
  "admin_updated_date" timestamptz NOT NULL DEFAULT now()
);
-- ---------------------------------------------------------------------
-- department_tb: แผนก/ฝ่าย/ทีมที่รับผิดชอบตั๋วงาน
-- ---------------------------------------------------------------------
CREATE TABLE "department_tb" (
  "department_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "department_code" varchar UNIQUE NOT NULL,
  "department_name_en" varchar NOT NULL,
  "department_name_th" varchar NOT NULL,
  "department_is_active" boolean NOT NULL DEFAULT true,
  "department_is_custom" boolean NOT NULL DEFAULT false,
  "department_created_at" timestamptz NOT NULL DEFAULT now(),
  "department_updated_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- reporter_tb: ผู้แจ้งที่ login ด้วย LINE (LIFF)
-- ---------------------------------------------------------------------
CREATE TABLE "reporter_tb" (
  "reporter_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reporter_line_user_id" varchar UNIQUE NOT NULL,
  "reporter_line_display_name" varchar,
  "reporter_line_picture_url" varchar,
  "reporter_created_at" timestamptz NOT NULL DEFAULT now(),
  "reporter_updated_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- symptom_tb: อาการที่พบบ่อยต่อแผนก (เรียนรู้อัตโนมัติ - upsert ทุกครั้งที่มีตั๋วใหม่
-- ---------------------------------------------------------------------
CREATE TABLE "symptom_tb" (
  "symptom_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "department_id" integer NOT NULL,
  "symptom_label" varchar NOT NULL,
  -- true = แอดมินพิมพ์เพิ่มเองตรง ๆ (ไม่ต้องรอสะสมยอด)
  "symptom_is_manual" boolean NOT NULL DEFAULT false,
  "symptom_hit_count" integer NOT NULL DEFAULT 0,
  "symptom_last_seen_at" timestamptz,
  "symptom_created_at" timestamptz NOT NULL DEFAULT now(),
  "symptom_updated_at" timestamptz NOT NULL DEFAULT now(),
  UNIQUE ("department_id", "symptom_label")
);

-- ---------------------------------------------------------------------
-- ticket_tb: ตั๋วงานหลัก
-- ---------------------------------------------------------------------
CREATE TABLE "ticket_tb" (
  "ticket_id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "ticket_no" varchar UNIQUE NOT NULL,                 
  "ticket_reporter_name" varchar NOT NULL,
  "ticket_reporter_contact" varchar NOT NULL,
  "ticket_location" varchar,
  "department_id" integer NOT NULL,

  "ticket_priority" varchar NOT NULL DEFAULT 'normal',  
  "ticket_triage_priority" varchar NOT NULL DEFAULT 'p3'
    CONSTRAINT "chk_ticket_triage_priority" CHECK ("ticket_triage_priority" IN ('p1', 'p2', 'p3', 'p4')),
  "ticket_urgent_detail" text,          

  "ticket_impact_level" varchar,                    
  "ticket_deadline_note" varchar,                 
  "ticket_deadline_date" date,
  "ticket_urgent_phone" varchar,                       
  -- ========================================================================

  "ticket_selected_symptoms" text[] NOT NULL DEFAULT ARRAY[]::text[],

  "reporter_id" integer,

  "ticket_subject" varchar NOT NULL,
  "ticket_description" text,
  "ticket_custom_department_note" varchar,        

  "ticket_status" varchar NOT NULL DEFAULT 'open',
  "ticket_assignee_admin_id" integer,
  "ticket_resolution_note" text,
  "ticket_closed_at" timestamptz,

  "ticket_assign_by" timestamptz,
  "ticket_resolve_by" timestamptz,
  "ticket_sla_breached" boolean NOT NULL DEFAULT false,
  "ticket_sla_warning_notified_at" timestamptz,
  "ticket_sla_breach_notified_at" timestamptz,
  "ticket_assign_breach_notified_at" timestamptz,
  "ticket_deadline_warning_notified_at" timestamptz,
  "ticket_deadline_breach_notified_at" timestamptz,
  "ticket_wait_started_at" timestamptz,
  "ticket_sla_paused_ms" bigint NOT NULL DEFAULT 0,
  "ticket_first_response_due_at" timestamptz,
  "ticket_first_responded_at" timestamptz,
  "ticket_resolve_due_at" timestamptz,
  "ticket_resolved_at" timestamptz,
  "ticket_confirmation_deadline" timestamptz,

  "ticket_idempotency_key" varchar UNIQUE,

  "ticket_created_at" timestamptz NOT NULL DEFAULT now(),
  "ticket_updated_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- ticket_image_tb: รูปภาพหลักฐานแนบ (สูงสุด 5 รูปต่อตั๋ว)
-- ---------------------------------------------------------------------
CREATE TABLE "ticket_image_tb" (
  "ticket_image_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ticket_id" uuid NOT NULL,
  "ticket_history_id" integer,                    
  "ticket_image_file_name" varchar NOT NULL,  
  "ticket_image_original_name" varchar NOT NULL,  
  "ticket_image_file_path" varchar NOT NULL,     
  "ticket_image_created_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- ticket_attachment_tb: ไฟล์แนบของบทสนทนา (ข้อความหรือบันทึกภายใน)
-- ---------------------------------------------------------------------
CREATE TABLE "ticket_attachment_tb" (
  "ticket_attachment_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ticket_id" uuid NOT NULL,
  "ticket_message_id" integer,
  "ticket_comment_id" integer,
  "ticket_attachment_file_name" varchar NOT NULL,
  "ticket_attachment_original_name" varchar NOT NULL,
  "ticket_attachment_file_path" varchar NOT NULL,
  "ticket_attachment_created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "chk_ticket_attachment_owner"
    CHECK ("ticket_message_id" IS NOT NULL OR "ticket_comment_id" IS NOT NULL)
);

-- ---------------------------------------------------------------------
-- ticket_history_tb: ประวัติเปลี่ยนสถานะ/ส่งต่อ (audit trail / timeline)
-- ---------------------------------------------------------------------
CREATE TABLE "ticket_history_tb" (
  "ticket_history_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ticket_id" uuid NOT NULL,
  "ticket_history_from_status" varchar NOT NULL,
  "ticket_history_to_status" varchar NOT NULL,
  "ticket_history_from_department_id" integer,         
  "ticket_history_to_department_id" integer,      
  "ticket_history_changed_by_admin_id" integer,       
  "ticket_history_note" text,
  "ticket_history_created_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- notification_tb: แจ้งเตือนฝั่งแอดมิน (fan-out-on-write ต่อผู้รับ)
-- ---------------------------------------------------------------------
CREATE TABLE "notification_tb" (
  "notification_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "notification_recipient_admin_id" integer NOT NULL,     
  "ticket_id" uuid,
  "notification_message" varchar NOT NULL,
  "notification_is_read" boolean NOT NULL DEFAULT false,
  "notification_created_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- reporter_notification_tb: แจ้งเตือนฝั่งผู้แจ้ง (fan-out-on-write ต่อ reporter)
-- ---------------------------------------------------------------------
CREATE TABLE "reporter_notification_tb" (
  "reporter_notification_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reporter_id" integer NOT NULL,
  "ticket_id" uuid NOT NULL,
  "reporter_notification_message" varchar NOT NULL,
  "reporter_notification_is_read" boolean NOT NULL DEFAULT false,
  "reporter_notification_created_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- ticket_message_tb: แชทในตั๋วระหว่างผู้แจ้ง (LINE) กับแอดมินผู้รับผิดชอบ
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "ticket_message_tb" (
  "ticket_message_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ticket_id" uuid NOT NULL,
  "ticket_message_sender_type" varchar NOT NULL,        -- user | admin
  "sender_reporter_id" integer,
  "sender_admin_id" integer,
  "ticket_message_text" text NOT NULL,
  "ticket_message_is_read" boolean NOT NULL DEFAULT false,
  "ticket_message_idempotency_key" varchar,
  "ticket_message_created_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- ticket_comment_tb: บันทึกภายในของแอดมิน (ผู้แจ้งไม่เห็น)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "ticket_comment_tb" (
  "ticket_comment_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ticket_id" uuid NOT NULL,
  "admin_id" integer,
  "ticket_comment_note" text NOT NULL,
  "ticket_comment_is_internal" boolean NOT NULL DEFAULT true,
  "ticket_comment_created_at" timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------
-- audit_log_tb: บันทึกการกระทำสำคัญของแอดมิน (ดูผ่านหน้า activity feed)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "audit_log_tb" (
  "audit_log_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "admin_id" integer,
  "audit_log_action" varchar NOT NULL,
  "audit_log_entity_type" varchar,
  "audit_log_entity_id" varchar,
  "audit_log_summary" text NOT NULL,
  "audit_log_metadata" jsonb,
  "audit_log_created_at" timestamptz NOT NULL DEFAULT now()
);

-- =====================================================================
-- Foreign Keys
-- =====================================================================
ALTER TABLE "symptom_tb"
  ADD FOREIGN KEY ("department_id") REFERENCES "department_tb" ("department_id") ON DELETE CASCADE;

ALTER TABLE "ticket_tb"
  ADD FOREIGN KEY ("department_id") REFERENCES "department_tb" ("department_id") ON DELETE RESTRICT;

ALTER TABLE "ticket_tb"
  ADD FOREIGN KEY ("reporter_id") REFERENCES "reporter_tb" ("reporter_id") ON DELETE SET NULL;

ALTER TABLE "ticket_tb"
  ADD FOREIGN KEY ("ticket_assignee_admin_id") REFERENCES "admin_tb" ("admin_id") ON DELETE SET NULL;

ALTER TABLE "ticket_image_tb"
  ADD FOREIGN KEY ("ticket_id") REFERENCES "ticket_tb" ("ticket_id") ON DELETE CASCADE;

ALTER TABLE "ticket_image_tb"
  ADD FOREIGN KEY ("ticket_history_id") REFERENCES "ticket_history_tb" ("ticket_history_id") ON DELETE CASCADE;

CREATE INDEX IF NOT EXISTS idx_ticket_image_ticket_history
  ON "ticket_image_tb" ("ticket_history_id")
  WHERE "ticket_history_id" IS NOT NULL;

ALTER TABLE "ticket_history_tb"
  ADD FOREIGN KEY ("ticket_id") REFERENCES "ticket_tb" ("ticket_id") ON DELETE CASCADE;

ALTER TABLE "ticket_history_tb"
  ADD FOREIGN KEY ("ticket_history_from_department_id") REFERENCES "department_tb" ("department_id") ON DELETE SET NULL;

ALTER TABLE "ticket_history_tb"
  ADD FOREIGN KEY ("ticket_history_to_department_id") REFERENCES "department_tb" ("department_id") ON DELETE SET NULL;

ALTER TABLE "ticket_history_tb"
  ADD FOREIGN KEY ("ticket_history_changed_by_admin_id") REFERENCES "admin_tb" ("admin_id") ON DELETE SET NULL;

ALTER TABLE "notification_tb"
  ADD FOREIGN KEY ("notification_recipient_admin_id") REFERENCES "admin_tb" ("admin_id") ON DELETE CASCADE;

ALTER TABLE "notification_tb"
  ADD FOREIGN KEY ("ticket_id") REFERENCES "ticket_tb" ("ticket_id") ON DELETE CASCADE;

ALTER TABLE "admin_tb"
  ADD FOREIGN KEY ("admin_department_id") REFERENCES "department_tb" ("department_id") ON DELETE RESTRICT;

ALTER TABLE "reporter_notification_tb"
  ADD FOREIGN KEY ("reporter_id") REFERENCES "reporter_tb" ("reporter_id") ON DELETE CASCADE;

ALTER TABLE "reporter_notification_tb"
  ADD FOREIGN KEY ("ticket_id") REFERENCES "ticket_tb" ("ticket_id") ON DELETE CASCADE;

-- =====================================================================
-- Indexes ที่แนะนำเพิ่ม (TypeORM synchronize สร้าง unique/PK ให้อัตโนมัติ
-- แต่ index ค้นหาทั่วไปแนะนำให้เพิ่มเองถ้าปิด synchronize บน production)
-- =====================================================================
CREATE INDEX IF NOT EXISTS idx_ticket_status ON "ticket_tb" ("ticket_status");
CREATE INDEX IF NOT EXISTS idx_ticket_department ON "ticket_tb" ("department_id");
CREATE INDEX IF NOT EXISTS idx_ticket_priority ON "ticket_tb" ("ticket_priority");
CREATE INDEX IF NOT EXISTS idx_ticket_created_at ON "ticket_tb" ("ticket_created_at");
CREATE INDEX IF NOT EXISTS idx_ticket_reporter ON "ticket_tb" ("reporter_id");
-- ใช้โดย SlaSchedulerService (รันทุก 5 นาที) ตอนหา ticket ที่ยังไม่ปิดเพื่อเช็ค SLA
CREATE INDEX IF NOT EXISTS idx_ticket_resolve_by ON "ticket_tb" ("ticket_resolve_by") WHERE "ticket_status" <> 'closed';
-- ใช้ตอนหาตั๋วที่รอผู้แจ้งยืนยันเกินเวลาแล้วต้อง auto-close
CREATE INDEX IF NOT EXISTS idx_ticket_confirmation_deadline ON "ticket_tb" ("ticket_confirmation_deadline")
  WHERE "ticket_status" = 'pending_confirmation';
-- ใช้โดยการค้นหาสาธารณะที่หน้า "ติดตามสถานะ" (TicketsService.searchPublic) ซึ่งเทียบแบบ
-- LOWER(ticket_no) = LOWER(:keyword) - unique index ปกติของ ticket_no ใช้ไม่ได้กับการ LOWER()
-- จึงต้องเป็น functional index ตัวนี้ ไม่งั้นทุกครั้งที่มีคนค้น = seq scan ทั้งตาราง
CREATE INDEX IF NOT EXISTS idx_ticket_no_lower ON "ticket_tb" (LOWER("ticket_no"));
-- ใช้ตอนผู้แจ้งที่ login LINE แล้วค้นในตั๋วของตัวเอง (กรอง reporter_id ก่อน แล้วเรียงตามวันที่)
CREATE INDEX IF NOT EXISTS idx_ticket_reporter_created_at
  ON "ticket_tb" ("reporter_id", "ticket_created_at" DESC);
CREATE INDEX IF NOT EXISTS idx_notification_recipient_unread
  ON "notification_tb" ("notification_recipient_admin_id", "notification_is_read");
CREATE INDEX IF NOT EXISTS idx_reporter_notification_recipient_unread
  ON "reporter_notification_tb" ("reporter_id", "reporter_notification_is_read");

-- Foreign keys ของตารางที่เพิ่มด้านบน
ALTER TABLE "ticket_message_tb"
  ADD CONSTRAINT "ticket_message_tb_ticket_id_fkey"
  FOREIGN KEY ("ticket_id") REFERENCES "ticket_tb" ("ticket_id") ON DELETE CASCADE;
ALTER TABLE "ticket_message_tb"
  ADD CONSTRAINT "ticket_message_tb_sender_reporter_id_fkey"
  FOREIGN KEY ("sender_reporter_id") REFERENCES "reporter_tb" ("reporter_id") ON DELETE SET NULL;
ALTER TABLE "ticket_message_tb"
  ADD CONSTRAINT "ticket_message_tb_sender_admin_id_fkey"
  FOREIGN KEY ("sender_admin_id") REFERENCES "admin_tb" ("admin_id") ON DELETE SET NULL;
ALTER TABLE "ticket_comment_tb"
  ADD CONSTRAINT "ticket_comment_tb_ticket_id_fkey"
  FOREIGN KEY ("ticket_id") REFERENCES "ticket_tb" ("ticket_id") ON DELETE CASCADE;
ALTER TABLE "ticket_comment_tb"
  ADD CONSTRAINT "ticket_comment_tb_admin_id_fkey"
  FOREIGN KEY ("admin_id") REFERENCES "admin_tb" ("admin_id") ON DELETE SET NULL;

-- Indexes สำหรับ query ที่ใช้บ่อยของตารางที่เพิ่ม
CREATE INDEX IF NOT EXISTS idx_ticket_message_ticket_created
  ON "ticket_message_tb" ("ticket_id", "ticket_message_created_at");
CREATE UNIQUE INDEX IF NOT EXISTS uq_ticket_message_idempotency
  ON "ticket_message_tb" ("ticket_id", "ticket_message_idempotency_key");
CREATE INDEX IF NOT EXISTS idx_ticket_attachment_message
  ON "ticket_attachment_tb" ("ticket_message_id");
CREATE INDEX IF NOT EXISTS idx_ticket_attachment_comment
  ON "ticket_attachment_tb" ("ticket_comment_id");
CREATE INDEX IF NOT EXISTS idx_ticket_comment_ticket
  ON "ticket_comment_tb" ("ticket_id", "ticket_comment_created_at");
CREATE INDEX IF NOT EXISTS idx_audit_log_created_at
  ON "audit_log_tb" ("audit_log_created_at" DESC);

